draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;

  // mom
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 20);
  ctx.lineTo(W/2 - 50, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 30);
  ctx.lineTo(W/2 - 70, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 30);
  ctx.lineTo(W/2 - 30, H/2 + 50);
  ctx.stroke();

  // child
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 20);
  ctx.lineTo(W/2 + 50, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 30);
  ctx.lineTo(W/2 + 30, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 30);
  ctx.lineTo(W/2 + 70, H/2 + 50);
  ctx.stroke();

  // tears
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(W/2 + 50 + Math.sin(t + i) * 10, H/2 + 20 + i * 10, 2, 0, 2 * Math.PI);
    ctx.fill();
  }

  // mom's arm
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 50);
  ctx.lineTo(W/2 - 50 + Math.cos(t) * 20, H/2 + 70);
  ctx.stroke();

  ctx.restore();
}
